import { useState, type ChangeEvent, type FormEvent } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms/Button/Button';
import { InputFieldTwo } from '@proton/components/index';
import PasswordInput from '@proton/components/components/v2/input/PasswordInput';

import { LumoIcon } from '../../components/LumoIcon/LumoIcon';

export type LocalAuthMode = 'signin' | 'signup';

export interface LocalAuthResult {
    UID: string;
    User: any;
}

const getErrorMessage = (error: any): string => {
    return error?.data?.Error ?? error?.message ?? c('collider_2025: Error').t`Something went wrong. Try again.`;
};

/**
 * Local sign-in / sign-up screen for the self-hosted instance.
 * Talks to /api/local/auth/* on this server (no external identity provider).
 */
const LocalAuthScreen = ({
    initialMode,
    onSession,
}: {
    initialMode: LocalAuthMode;
    onSession: (result: LocalAuthResult) => void;
}) => {
    const [mode, setMode] = useState<LocalAuthMode>(initialMode);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async (event: FormEvent) => {
        event.preventDefault();
        setError(null);

        if (mode === 'signup' && password !== confirmPassword) {
            setError(c('collider_2025: Error').t`Passwords do not match`);
            return;
        }

        setLoading(true);
        try {
            const response = await fetch(`/api/local/auth/${mode}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
            });
            const json = await response.json().catch(() => null);
            if (!response.ok) {
                throw { data: json };
            }
            onSession({ UID: json.UID, User: json.User });
        } catch (submitError: any) {
            setError(getErrorMessage(submitError));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex h-full w-full items-center justify-center bg-norm p-4 overflow-auto">
            <div className="w-full max-w-custom rounded-lg border border-weak bg-weak p-7" style={{ '--max-w-custom': '26rem' } as any}>
                <div className="flex flex-column items-center gap-3 mb-6">
                    <LumoIcon name="Cat" size={40} className="color-primary" />
                    <h1 className="text-2xl text-bold mb-0">
                        {mode === 'signin'
                            ? c('collider_2025: Title').t`Sign in to Lumo`
                            : c('collider_2025: Title').t`Create your Lumo account`}
                    </h1>
                    <p className="color-weak text-sm m-0 text-center">
                        {c('collider_2025: Info')
                            .t`Self-hosted instance. Accounts and data are stored locally on this server.`}
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="flex flex-column gap-4">
                    <InputFieldTwo
                        id="local-auth-username"
                        label={c('collider_2025: Label').t`Username`}
                        value={username}
                        onChange={(event: ChangeEvent<HTMLInputElement>) => setUsername(event.target.value)}
                        placeholder={mode === 'signup' ? c('collider_2025: Placeholder').t`pick-a-name` : undefined}
                        autoFocus
                    />
                    <InputFieldTwo
                        id="local-auth-password"
                        label={c('collider_2025: Label').t`Password`}
                        as={PasswordInput}
                        value={password}
                        onChange={(event: ChangeEvent<HTMLInputElement>) => setPassword(event.target.value)}
                        placeholder={mode === 'signup' ? c('collider_2025: Placeholder').t`at least 4 characters` : undefined}
                    />
                    {mode === 'signup' && (
                        <InputFieldTwo
                            id="local-auth-password-confirm"
                            label={c('collider_2025: Label').t`Confirm password`}
                            as={PasswordInput}
                            value={confirmPassword}
                            onChange={(event: ChangeEvent<HTMLInputElement>) => setConfirmPassword(event.target.value)}
                        />
                    )}

                    {error && <span className="color-danger text-sm">{error}</span>}

                    <Button type="submit" size="large" loading={loading} disabled={!username || !password}>
                        {mode === 'signin'
                            ? c('collider_2025: Action').t`Sign in`
                            : c('collider_2025: Action').t`Create account`}
                    </Button>

                    <Button
                        type="button"
                        shape="ghost"
                        onClick={() => {
                            setMode(mode === 'signin' ? 'signup' : 'signin');
                            setError(null);
                        }}
                    >
                        {mode === 'signin'
                            ? c('collider_2025: Action').t`Need an account? Create one`
                            : c('collider_2025: Action').t`Already have an account? Sign in`}
                    </Button>

                    <Button
                        type="button"
                        shape="outline"
                        onClick={() => {
                            window.location.href = '/guest';
                        }}
                    >
                        {c('collider_2025: Action').t`Continue as guest`}
                    </Button>
                </form>
            </div>
        </div>
    );
};

export default LocalAuthScreen;
