import { Suspense, lazy, useState } from 'react';
import { Router } from 'react-router-dom';
import createSagaMiddleware from 'redux-saga';

import {
    addressesThunk,
    initEvent,
    serverEvent,
    userSettingsThunk,
    userThunk,
    welcomeFlagsActions,
} from '@proton/account';
import * as bootstrap from '@proton/account/bootstrap';
import { FeatureCode, fetchFeatures } from '@proton/features';
import {
    ApiProvider,
    AuthenticationProvider,
    DrawerProvider,
    ErrorBoundary,
    EventManagerProvider,
    ProtonApp,
    StandardErrorPage,
    StandardPrivateApp,
} from '@proton/components';
import useEffectOnce from '@proton/hooks/useEffectOnce';
import { ProtonStoreProvider } from '@proton/redux-shared-store/sharedProvider';
import createApi from '@proton/shared/lib/api/createApi';
import { getSilentApi } from '@proton/shared/lib/api/helpers/customConfig';
import { DRAWER_VISIBILITY } from '@proton/shared/lib/interfaces';
import { FlagProvider } from '@proton/unleash/proxy';

import ConditionalNotificationsChildren from '../../components/ConditionalNotificationsChildren';
import { IndexedDBConnectionMonitor } from '../../components/IndexedDBConnectionMonitor';
import LumoLoader from '../../components/Loading/LumoLoader';
import config from '../../config';
import { isIndexedDBAvailable } from '../../indexedDb/util';
import { DbApi } from '../../indexedDb/db';
import locales from '../../locales';
import { LumoThemeProvider } from '../../providers';
import { lumoEventLoop } from '../../redux/eventLoop';
import { createLumoListenerMiddleware } from '../../redux/listeners';
import { rootSaga } from '../../redux/sagas';
import type { LumoSaga, LumoSagaContext, LumoStore } from '../../redux/store';
import { extendStore, setupStore } from '../../redux/store';
import { setStoreRef } from '../../redux/storeRef';
import { extraThunkArguments } from '../../redux/thunk';
import { LumoApi } from '../../remote/api';
import noop from '@proton/utils/noop';

import LocalAuthScreen, { type LocalAuthResult } from './LocalAuthScreen';

const RouterContainerLazy = lazy(
    () =>
        import(
            /* webpackChunkName: "RouterContainer" */
            /* webpackFetchPriority: "high" */
            './RouterContainer'
        )
);

const LOCAL_SESSION_KEY = 'lumo.local.session';

const readLocalSession = (): string | null => {
    try {
        const raw = window.localStorage.getItem(LOCAL_SESSION_KEY);
        if (!raw) {
            return null;
        }
        const parsed = JSON.parse(raw);
        return typeof parsed?.UID === 'string' ? parsed.UID : null;
    } catch {
        return null;
    }
};

const writeLocalSession = (result: LocalAuthResult) => {
    window.localStorage.setItem(LOCAL_SESSION_KEY, JSON.stringify({ UID: result.UID }));
};

/**
 * Self-hosted authentication entry: local accounts against this server's
 * /api/local/auth/* endpoints, then the standard authenticated Lumo boot
 * (same shell/providers as AuthApp, minus Proton account plumbing).
 */
const LocalAuthApp = () => {
    const [uid, setUid] = useState<string | null>(() => readLocalSession());
    const [bootError, setBootError] = useState<string | null>(null);
    const [ready, setReady] = useState<
        | {
              user: any;
              showDrawerSidebar: boolean;
              store: LumoStore;
          }
        | null
    >(null);

    // Ensure the authentication store reflects the chosen session before boot.
    useEffectOnce(() => {
        const bootUid = uid;
        if (!bootUid) {
            return;
        }
        void (async () => {
            try {
                const authentication = bootstrap.createAuthentication({
                    onUID: (nextUid: string | undefined) => {
                        if (!nextUid) {
                            window.localStorage.removeItem(LOCAL_SESSION_KEY);
                            window.location.href = '/login';
                        }
                    },
                });
                bootstrap.init({ config, authentication, locales });
                authentication.login({
                    UID: bootUid,
                    localID: 0,
                    keyPassword: '',
                    clientKey: '',
                    offlineKey: undefined,
                    persistedSession: {
                        UID: bootUid,
                        UserID: bootUid,
                        localID: 0,
                        accessType: 'default' as any,
                        persistent: true,
                        trusted: true,
                        payloadVersion: 2,
                        payloadType: 'default',
                        persistedAt: Date.now(),
                        source: 'login' as any,
                    },
                });

                const api = createApi({ config });
                const silentApi = getSilentApi(api);
                const pathname = window.location.pathname;
                const history = bootstrap.createHistory({
                    sessionResult: { basename: undefined, url: undefined, reloadDocument: false },
                    pathname,
                });
                const unleashClient = bootstrap.createUnleash({ api: silentApi });

                const listenerMiddleware = createLumoListenerMiddleware({ extra: extraThunkArguments });
                const sagaMiddleware: LumoSaga = createSagaMiddleware<LumoSagaContext>({
                    context: {} as LumoSagaContext,
                });
                const store = setupStore({ preloadedState: undefined, listenerMiddleware, sagaMiddleware });
                setStoreRef(store);
                const dispatch = store.dispatch;

                extendStore({ config, api, authentication, unleashClient, history });

                const [user, userSettings] = await Promise.all([
                    dispatch(userThunk()),
                    dispatch(userSettingsThunk()),
                ]);

                dispatch(fetchFeatures([FeatureCode.EarlyAccessScope] as any)).catch(noop);
                dispatch(welcomeFlagsActions.initial(userSettings));
                await bootstrap.loadLocales({ userSettings, locales });

                dispatch(initEvent({ User: user }));

                const showDrawerSidebar = userSettings?.HideSidePanel === DRAWER_VISIBILITY.SHOW;

                // Addresses: needed by some account slices; local server provides one.
                dispatch(addressesThunk()).catch(noop);

                const dbApi = new DbApi(user.ID);
                await dbApi.initialize();
                const lumoApi = new LumoApi(uid);
                extendStore({ dbApi, lumoApi });
                sagaMiddleware.setContext({ dbApi, lumoApi });

                sagaMiddleware.run(rootSaga);

                const eventManager = bootstrap.eventManager({ api: silentApi });
                const lumoEventManager = bootstrap.lumoEventManager({ api: silentApi });
                extendStore({ eventManager, lumoEventManager });
                eventManager.subscribe((event: any) => dispatch(serverEvent(event)));
                lumoEventManager.subscribe(async (event: any) => {
                    const promises: Promise<void>[] = [];
                    dispatch(lumoEventLoop({ event, promises }));
                    await Promise.all(promises);
                });
                eventManager.start();
                lumoEventManager.start();

                setReady({ user, showDrawerSidebar, store });
            } catch (error: any) {
                if (!isIndexedDBAvailable()) {
                    setBootError('IndexedDB is not available in this browser.');
                    return;
                }
                setBootError(error?.message ?? String(error));
            }
        })();
    });

    if (!uid) {
        return (
            <LumoThemeProvider>
                <LocalAuthScreen
                    initialMode={window.location.pathname.startsWith('/signup') ? 'signup' : 'signin'}
                    onSession={(result) => {
                        writeLocalSession(result);
                        setUid(result.UID);
                    }}
                />
            </LumoThemeProvider>
        );
    }

    if (bootError) {
        return (
            <LumoThemeProvider>
                <div className="flex h-full w-full items-center justify-center bg-norm p-4">
                    <div className="text-center">
                        <p className="color-danger">{bootError}</p>
                        <button
                            className="link"
                            onClick={() => {
                                window.localStorage.removeItem(LOCAL_SESSION_KEY);
                                window.location.href = '/login';
                            }}
                        >
                            Back to sign in
                        </button>
                    </div>
                </div>
            </LumoThemeProvider>
        );
    }

    if (!ready) {
        return (
            <LumoThemeProvider>
                <LumoLoader />
            </LumoThemeProvider>
        );
    }

    const loader = <LumoLoader />;

    return (
        <ProtonApp config={config}>
            <ProtonStoreProvider store={ready.store}>
                <AuthenticationProvider store={extraThunkArguments.authentication}>
                    <ApiProvider api={extraThunkArguments.api}>
                        <DrawerProvider defaultShowDrawerSidebar={ready.showDrawerSidebar}>
                            <FlagProvider unleashClient={extraThunkArguments.unleashClient} startClient={false}>
                                <Router history={extraThunkArguments.history}>
                                    <EventManagerProvider eventManager={extraThunkArguments.eventManager}>
                                        <ErrorBoundary big component={<StandardErrorPage big />}>
                                            <IndexedDBConnectionMonitor />
                                            <ConditionalNotificationsChildren />
                                            <StandardPrivateApp noNotifications>
                                                <LumoThemeProvider>
                                                    <Suspense fallback={loader}>
                                                        <RouterContainerLazy />
                                                    </Suspense>
                                                </LumoThemeProvider>
                                            </StandardPrivateApp>
                                        </ErrorBoundary>
                                    </EventManagerProvider>
                                </Router>
                            </FlagProvider>
                        </DrawerProvider>
                    </ApiProvider>
                </AuthenticationProvider>
            </ProtonStoreProvider>
        </ProtonApp>
    );
};

export default LocalAuthApp;
